import itertools

def stmts(J,E,S):
    jack = (E == J)                      # E iff J
    eliz = ((not J) <= (not S))          # not J -> not S
    sam  = ((not E) <= (not J))          # E -> not J
    return jack, eliz, sam

sols=[]
for J,E,S in itertools.product([True,False],repeat=3):
    jack, eliz, sam = stmts(J,E,S)
    if (J == jack) and (E == eliz) and (S == sam):
        sols.append((J,E,S))

print("full solutions (J,E,S):", sols)

print("rows satisfying ONLY Jack's equation J == (E==J):")
for J,E,S in itertools.product([True,False],repeat=3):
    if J == (E==J):
        print("   J=%s E=%s S=%s" % (J,E,S))
