import itertools

names = ['Grace','Penelope','Jack','James','Riley']
sols=[]
sols_xor=[]
for G,P,J,M,R in itertools.product([True,False],repeat=5):
    s1 = (not J)                      # Grace: Jack is a knave
    s2 = (M or R)                     # Penelope: James knight OR Riley knight (inclusive)
    s3 = ((not G) == R)               # Jack: Grace is knave iff Riley is knight
    s4 = ((not J) and R)              # James: Jack knave AND Riley knight
    s5 = M                            # Riley: James is not a knave
    ok = (G==s1) and (P==s2) and (J==s3) and (M==s4) and (R==s5)
    if ok:
        sols.append((G,P,J,M,R))
    # exclusive-or variant for Penelope's statement
    s2x = (M != R)
    okx = (G==s1) and (P==s2x) and (J==s3) and (M==s4) and (R==s5)
    if okx:
        sols_xor.append((G,P,J,M,R))

def show(s):
    return ", ".join(f"{n}={'knight' if v else 'knave'}" for n,v in zip(names,s))

print("inclusive-or solutions:", len(sols))
for s in sols: print("  ", show(s))
print("exclusive-or solutions:", len(sols_xor))
for s in sols_xor: print("  ", show(s))
